local function normalize(name)
    return name:gsub("%s+", ""):lower()
end

local KeyframePlayer = {}
KeyframePlayer.__index = KeyframePlayer

function KeyframePlayer.new(model)
    local self = setmetatable({}, KeyframePlayer)
    self.Model = model
    self.Joints = {}
    self.IsPlaying = false
    self.CurrentSession = 0
    
    for _, v in ipairs(model:GetDescendants()) do
        if v:IsA("Motor6D") or v:IsA("Bone") then
            self.Joints[normalize(v.Name)] = v
        end
    end
    
    return self
end

function KeyframePlayer:FindPose(poses, name)
    local target = normalize(name)
    for _, pose in ipairs(poses) do
        if normalize(pose.Name) == target then
            return pose
        end
    end
    return nil
end

function KeyframePlayer:ApplyInterpolatedPoses(poses1, poses2, alpha)
    for _, p1 in ipairs(poses1) do
        local p2 = self:FindPose(poses2, p1.Name)
        local joint = self.Joints[normalize(p1.Name)]
        
        if joint then
            local cf1 = p1.CFrame
            local cf2 = p2 and p2.CFrame or cf1
            joint.Transform = cf1:Lerp(cf2, alpha)
        end
        
        if p1.SubPoses then
            self:ApplyInterpolatedPoses(p1.SubPoses, p2 and p2.SubPoses or {}, alpha)
        end
    end
end

function KeyframePlayer:Play(animName, loop)
    local data = KeyframeData[animName]
    if not data then return end
    
    self.IsPlaying = true
    self.CurrentSession = self.CurrentSession + 1
    local playSession = self.CurrentSession
    
    task.spawn(function()
        while self.IsPlaying and self.CurrentSession == playSession do
            local keyframes = data.Keyframes
            for i = 1, #keyframes do
                if not self.IsPlaying or self.CurrentSession ~= playSession then break end
                
                local kf1 = keyframes[i]
                local kf2 = keyframes[i % #keyframes + 1]
                local duration = kf2.Time - kf1.Time
                if duration <= 0 then duration = 0.05 end
                
                local start = tick()
                while tick() - start < duration do
                    if not self.IsPlaying or self.CurrentSession ~= playSession then break end
                    local alpha = (tick() - start) / duration
                    self:ApplyInterpolatedPoses(kf1.Poses, kf2.Poses, alpha)
                    RunService.Heartbeat:Wait()
                end
            end
            if not loop then break end
        end
        if self.CurrentSession == playSession then
            self.IsPlaying = false
        end
    end)
end

function KeyframePlayer:Stop()
    self.IsPlaying = false
    self.CurrentSession = self.CurrentSession + 1
end

local playerObj = nil

local function loadCustomAsset(url, filename)
    if not isfile(filename) then
        writefile(filename, game:HttpGet(url))
    end
    return getcustomasset(filename)
end

local function setupAudio()
    if reskin.audio then return end
    
    local success, soundId = pcall(function()
        return loadCustomAsset(AUDIO_URL, AUDIO_FILENAME)
    end)
    
    if success then
        local sound = Instance.new("Sound")
        sound.Name = "BlazeTheme"
        sound.SoundId = soundId
        sound.Looped = true
        sound.Volume = 2
        sound.Parent = game:GetService("SoundService")
        sound:Play()
        reskin.audio = sound
        print("✅ Audio Started Playing Immediately")
    else
        warn("❌ Failed to load GitHub audio")
    end
end

local function getPlayerModel()
    local playersFolder = workspace:FindFirstChild("Players")
    local model = playersFolder and playersFolder:FindFirstChild(player.Name)
    return model or player.Character
end

local function isTargetCharacter()
    local model = getPlayerModel()
    if not model then return false end
    local charAttr = model:GetAttribute("Character") or player:GetAttribute("Character")
    if not charAttr then return false end
    local charName = tostring(charAttr)
    for _, t in ipairs(targetCharacters) do
        if charName == t then return true end
    end
    return false
end

local function purgeScripts(model)
    for _, child in ipairs(model:GetDescendants()) do
        if child:IsA("LocalScript") or child:IsA("Script") then child:Destroy() end
    end
end

local function switchToLMSModel()
    if reskin.isInLMS or not player.Character then return end
    reskin.isInLMS = true
    
    print("🔄 Switching to LMS Model...")
    
    if reskin.model then
        for _, v in ipairs(reskin.model:GetDescendants()) do
            if v:IsA("BasePart") then v.Transparency = 1 end
        end
    end
    
    local ok, objects = pcall(game.GetObjects, game, "rbxassetid://" .. LMS_ASSET_ID)
    if not ok or #objects == 0 then return end
    
    local lmsModel = objects[1]:Clone()
    lmsModel.Name = "LMS_Model"
    purgeScripts(lmsModel)
    
    local char = player.Character
    local playersFolder = workspace:FindFirstChild("Players")
    local visualFolder = playersFolder and playersFolder:FindFirstChild(player.Name)
    lmsModel.Parent = visualFolder or char
    
    local hrp = char:FindFirstChild("HumanoidRootPart")
    local newHrp = lmsModel:FindFirstChild("HumanoidRootPart") or lmsModel:FindFirstChildWhichIsA("BasePart")
    
    if hrp and newHrp then
        newHrp.Anchored = true
        newHrp.Transparency = 1
        for _, v in ipairs(lmsModel:GetDescendants()) do
            if v:IsA("BasePart") then v.CanCollide = false; v.Transparency = 0 end
        end
        
        task.spawn(function()
            while reskin.isInLMS and lmsModel.Parent and hrp.Parent do
                newHrp.CFrame = hrp.CFrame * CFrame.new(0, 1.1, 0)
                task.wait()
            end
        end)
    end
    
    reskin.lmsModel = lmsModel
    print("✅ LMS Model Loaded")
end

local function revertToNormalModel()
    if not reskin.isInLMS then return end
    reskin.isInLMS = false
    if reskin.lmsModel then reskin.lmsModel:Destroy(); reskin.lmsModel = nil end
    if reskin.model then
        for _, v in ipairs(reskin.model:GetDescendants()) do
            if v:IsA("BasePart") then v.Transparency = 0 end
        end
    end
    print("✅ Reverted to Normal Model")
end

local function monitorLMS()
    RunService.Heartbeat:Connect(function()
        if not reskin.isTarget then return end
        local soloTheme = game:GetService("ReplicatedStorage"):FindFirstChild("ClientAssets")
            and game.ReplicatedStorage.ClientAssets:FindFirstChild("Sounds")
            and game.ReplicatedStorage.ClientAssets.Sounds:FindFirstChild("mus")
            and game.ReplicatedStorage.ClientAssets.Sounds.mus:FindFirstChild("Game")
            and game.ReplicatedStorage.ClientAssets.Sounds.mus.Game:FindFirstChild("Round")
            and game.ReplicatedStorage.ClientAssets.Sounds.mus.Game.Round:FindFirstChild("SoloTheme")
            and game.ReplicatedStorage.ClientAssets.Sounds.mus.Game.Round.SoloTheme:FindFirstChild("SonicSolo")
            
        if soloTheme and soloTheme.IsPlaying then
            if not reskin.isInLMS then switchToLMSModel() end
        else
            if reskin.isInLMS then revertToNormalModel() end
        end
    end)
end

local function loadReskinModel(char)
    if not reskin.isTarget then
        if reskin.model then reskin.model:Destroy() end
        reskin.model = nil
        playerObj = nil
        return
    end
    if reskin.model then return end

    local success, objects = pcall(game.GetObjects, game, "rbxassetid://" .. MODEL_ID)
    if not success or #objects == 0 then return end

    reskin.model = objects[1]:Clone()
    reskin.model.Name = "ShadowBlazeModel"
    purgeScripts(reskin.model)

    local mainAnimator = char.Humanoid:FindFirstChildOfClass("Animator")
    if mainAnimator then mainAnimator:Destroy() end

    for _, part in ipairs(reskin.model:GetDescendants()) do
        if part:IsA("BasePart") then
            part.Anchored = false; part.CanCollide = false; part.Massless = true
        end
    end

    reskin.model.Parent = char
    local hrp = char:WaitForChild("HumanoidRootPart")
    local primary = reskin.model.PrimaryPart or reskin.model:FindFirstChild("HumanoidRootPart") or reskin.model:FindFirstChildWhichIsA("BasePart")

    if hrp and primary then
        reskin.model:SetPrimaryPartCFrame(hrp.CFrame)
        local motor = Instance.new("Motor6D")
        motor.Part0 = hrp; motor.Part1 = primary; motor.Parent = hrp
        reskin.motor = motor
    end

    char.Humanoid.HipHeight = 2.7
    playerObj = KeyframePlayer.new(reskin.model)
end

local function playAnim(name, loop)
    if not playerObj then return end
    if reskin.currentAnim == name and playerObj.IsPlaying then return end
    playerObj:Stop()
    playerObj:Play(name, loop)
    reskin.currentAnim = name
end

local function updateMovement(char)
    if reskin.emotePlaying or reskin.isSliding or reskin.isShooting or isSlamming or reskin.isInLMS then return end
    local humanoid = char:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end
    local state = humanoid:GetState()

    if state == Enum.HumanoidStateType.Jumping or state == Enum.HumanoidStateType.Freefall then
        playAnim("idle", true)
    else
        local moving = humanoid.MoveDirection.Magnitude > 0.1
        local model = getPlayerModel()
        local speedBoost = model and model:GetAttribute("SpeedBoost") or 1
        if moving then
            if speedBoost >= 2 then playAnim("run / sliding", true) else playAnim("walk", true) end
        else
            playAnim("idle", true)
        end
    end
end

local function executeSlamBounce(hrp, hitPart)
    if slamConn then slamConn:Disconnect(); slamConn = nil end
    local fallDistance = math.max(0, startSlamY - hrp.Position.Y)
    local totalBounce = math.min(BASE_BOUNCE + (fallDistance * FALL_MULTIPLIER), MAX_BOUNCE)
    hrp.AssemblyLinearVelocity = Vector3.new(hrp.AssemblyLinearVelocity.X, totalBounce, hrp.AssemblyLinearVelocity.Z)
    task.wait(0.3); isSlamming = false
end

local function initiateGroundSlam()
    local char = player.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp or isSlamming then return end
    isSlamming = true; startSlamY = hrp.Position.Y; playAnim("idle", false)
    hrp.AssemblyLinearVelocity = Vector3.new(hrp.AssemblyLinearVelocity.X, SLAM_DOWNWARD_SPEED, hrp.AssemblyLinearVelocity.Z)
    local raycastParams = RaycastParams.new()
    raycastParams.FilterDescendantsInstances = {char}
    raycastParams.FilterType = Enum.RaycastFilterType.Exclude
    slamConn = RunService.Heartbeat:Connect(function()
        local hit = workspace:Raycast(hrp.Position, Vector3.new(0, -6, 0), raycastParams)
        if hit then executeSlamBounce(hrp, hit.Instance) end
    end)
end

RunService.RenderStepped:Connect(function(dt)
    local char = player.Character
    if not char or not reskin.isTarget then return end
    local humanoid = char:FindFirstChildOfClass("Humanoid")
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not (humanoid and hrp) then return end
    local model = getPlayerModel()
    local currentBoost = model and model:GetAttribute("SpeedBoost") or 1
    local moving = humanoid.MoveDirection.Magnitude > 0.05
    if moving then currentBoost = math.min(MAX_BOOST, currentBoost + ATTRIBUTE_ACCEL_RATE * dt)
    else currentBoost = math.max(MIN_BOOST, currentBoost - ATTRIBUTE_DECEL_RATE * dt) end
    if model then model:SetAttribute("SpeedBoost", currentBoost) end
    local moveDir = humanoid.MoveDirection
    if moveDir.Magnitude > 0 then
        local effectiveSpeed = 16 + (currentBoost - 1) * 25
        hrp.CFrame = hrp.CFrame + moveDir.Unit * (effectiveSpeed * dt)
    end
    updateMovement(char)
end)

UserInputService.InputBegan:Connect(function(input, processed)
    if processed or not reskin.isTarget then return end
    if input.KeyCode == Enum.KeyCode.G then
        reskin.emotePlaying = not reskin.emotePlaying
        if reskin.emotePlaying then playAnim("shadowpose2", true) else reskin.currentAnim = nil end
    elseif input.KeyCode == Enum.KeyCode.Q then
        if not reskin.isShooting then
            reskin.isShooting = true; playAnim("shoot", false); task.wait(1); reskin.isShooting = false; reskin.currentAnim = nil
        end
    elseif input.KeyCode == Enum.KeyCode.E then
        if not reskin.isSliding then
            reskin.isSliding = true; playAnim("run / sliding", true); task.wait(3); reskin.isSliding = false; reskin.currentAnim = nil
        end
    elseif input.KeyCode == Enum.KeyCode.R then
        initiateGroundSlam()
    end
end)

player.CharacterAdded:Connect(function(char)
    reskin.isTarget = isTargetCharacter()
    if reskin.isTarget then loadReskinModel(char) end
end)

RunService.Heartbeat:Connect(function()
    local char = player.Character
    if not char then return end
    local currentTarget = isTargetCharacter()
    if currentTarget ~= reskin.isTarget then
        reskin.isTarget = currentTarget
        if currentTarget then loadReskinModel(char) else
            if reskin.model then reskin.model:Destroy() end
            reskin.model = nil
        end
    end
end)

-- Start immediately
setupAudio()
monitorLMS()
if player.Character then
    reskin.isTarget = isTargetCharacter()
    if reskin.isTarget then loadReskinModel(player.Character) end
end
